            NULL::INT
        FROM estado_clinica_catalogo c
        WHERE c.activo
        ORDER BY c.categoria, c.orden, c.valor;

    ELSIF p_opcion = 16 THEN
        RETURN QUERY
        SELECT * FROM public.fn_gestion_clinica_payload(
            TRUE,
            NULL,
            jsonb_build_object(
                'regiones', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object('id', r.id_region, 'nombre', r.nombre) ORDER BY r.orden)
                    FROM region r
                ), '[]'::JSONB),
                'tipos_alergia', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object('id', t.id_tipo_alergia, 'nombre', t.nombre) ORDER BY t.nombre)
                    FROM tipo_alergia t
                    WHERE t.activo
                ), '[]'::JSONB),
                'tipos_atencion', COALESCE((
                    SELECT jsonb_agg(c.valor ORDER BY c.orden)
                    FROM estado_clinica_catalogo c
                    WHERE c.categoria = 'tipos_atencion' AND c.activo
                ), '[]'::JSONB),
                'areas_derivacion', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object('id', a.id_area, 'nombre', a.nombre) ORDER BY a.nombre)
                    FROM area_profesional a
                                        WHERE a.activo
                                            AND LOWER(TRANSLATE(a.nombre, 'ÁÉÍÓÚáéíóúÑñ', 'AEIOUaeiounn')) NOT LIKE '%administr%'
                                            AND LOWER(TRANSLATE(a.nombre, 'ÁÉÍÓÚáéíóúÑñ', 'AEIOUaeiounn')) NOT LIKE '%integracion de sistemas%'
                                            AND LOWER(TRANSLATE(a.nombre, 'ÁÉÍÓÚáéíóúÑñ', 'AEIOUaeiounn')) NOT LIKE '%tecnologias de la informacion%'
                                            AND EXISTS (
                                                    SELECT 1
                                                    FROM profesional_salud ps
                                                    INNER JOIN disponibilidad_profesional dp ON dp.id_profesional = ps.id_profesional
                                                    WHERE ps.id_area = a.id_area
                                                        AND ps.activo
                                                        AND dp.disponible
                                                        AND (dp.fecha_inicio IS NULL OR dp.fecha_inicio <= CURRENT_DATE)
                                                        AND (dp.fecha_fin IS NULL OR dp.fecha_fin >= CURRENT_DATE)
                                            )
                ), '[]'::JSONB),
                'estado_inicial', (
                    SELECT c.valor
                    FROM estado_clinica_catalogo c
                    WHERE c.categoria = 'atenciones' AND c.valor = 'Programada' AND c.activo
                    LIMIT 1
                )
            )
        );

    ELSIF p_opcion = 17 THEN
        RETURN QUERY
        SELECT * FROM public.fn_gestion_clinica_payload(
            TRUE,
            NULL,
            jsonb_build_object(
                'comunas', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object('id', co.id_comuna, 'nombre', co.nombre) ORDER BY co.nombre)
                    FROM comuna co
                    WHERE co.id_region::TEXT = p_id
                ), '[]'::JSONB)
            )
        );

    ELSIF p_opcion = 18 THEN
        SELECT u.id_profesional AS id_profesional,
               u.id_establecimiento AS id_establecimiento,
             ps.id_area AS id_area,
               TRIM(COALESCE(u.nombres, '') || ' ' || COALESCE(u.apellidos, '')) AS profesional,
               (r.codigo = 'SUPER_ADMIN' OR COALESCE(r.es_super_admin, FALSE)) AS es_super_admin,
               r.codigo AS codigo_rol,
               r.nombre AS nombre_rol,
               (r.codigo = 'ADMIN') AS es_administrador,
               e.nombre AS centro_nombre,
               e.tipo_establecimiento AS centro_tipo,
               e.direccion AS centro_direccion,
               e.comuna AS centro_comuna,
               e.region AS centro_region
        INTO v_usuario
        FROM usuario_sistema u
        INNER JOIN rol r ON r.id_rol = u.id_rol
        LEFT JOIN profesional_salud ps ON ps.id_profesional = u.id_profesional
        LEFT JOIN establecimiento_salud e ON e.id_establecimiento = u.id_establecimiento
        WHERE u.id_usuario::TEXT = p_id
        LIMIT 1;

        IF v_usuario.profesional IS NULL THEN
            RETURN QUERY SELECT * FROM public.fn_gestion_clinica_payload(FALSE, NULL, '{}'::JSONB);
            RETURN;
        END IF;

        RETURN QUERY
        SELECT * FROM public.fn_gestion_clinica_payload(
            TRUE,
            NULL,
            jsonb_build_object(
                'id_profesional', v_usuario.id_profesional,
                'id_establecimiento', v_usuario.id_establecimiento,
                'id_area', v_usuario.id_area,
                'es_super_admin', v_usuario.es_super_admin,
                'codigo_rol', v_usuario.codigo_rol,
                'nombre_rol', v_usuario.nombre_rol,
                'es_administrador', v_usuario.es_administrador,
                'profesional', v_usuario.profesional,
                'centro', CASE
                    WHEN v_usuario.es_super_admin THEN jsonb_build_object(
                        'nombre', 'SICHCP',
                        'tipo', U&'Administraci\00f3n Central',
                        'direccion', 'Nivel Central',
                        'comuna', 'Santiago',
                        'region', 'Metropolitana de Santiago'
                    )
                    ELSE jsonb_build_object(
                        'nombre', COALESCE(v_usuario.centro_nombre, U&'Red P\00fablica SICHCP'),
                        'tipo', COALESCE(v_usuario.centro_tipo, 'CENTRO DE SALUD'),
                        'direccion', COALESCE(v_usuario.centro_direccion, ''),
                        'comuna', COALESCE(v_usuario.centro_comuna, ''),
                        'region', COALESCE(v_usuario.centro_region, '')
                    )
                END
            )
        );

    ELSIF p_opcion = 19 THEN
        IF v_clean_rut IS NULL OR v_clean_rut = '' THEN
            RETURN QUERY SELECT * FROM public.fn_gestion_clinica_payload(FALSE, NULL, '{}'::JSONB);
            RETURN;
        END IF;

        SELECT p.id_paciente AS id_paciente,
               p.rut AS rut,
               p.nombres AS nombres,
               COALESCE(p.apellido_paterno, split_part(COALESCE(p.apellidos, ''), ' ', 1)) AS apellido_paterno,
               COALESCE(p.apellido_materno, NULLIF(btrim(substr(COALESCE(p.apellidos, ''), length(split_part(COALESCE(p.apellidos, ''), ' ', 1)) + 1)), '')) AS apellido_materno,
               to_char(p.fecha_nacimiento, 'YYYY-MM-DD') AS fecha_nacimiento,
               (CASE
                   WHEN LOWER(p.sexo) IN ('m', 'masculino') THEN 'M'
                   WHEN LOWER(p.sexo) IN ('f', 'femenino') THEN 'F'
                   ELSE ''
               END) AS sexo,
               p.telefono AS telefono,
               p.direccion AS direccion,
               p.id_region AS id_region,
               p.id_comuna AS id_comuna
        INTO v_paciente
        FROM paciente p
        WHERE LOWER(REPLACE(REPLACE(p.rut, '.', ''), '-', '')) = v_clean_rut
        LIMIT 1;

        IF v_paciente.id_paciente IS NULL THEN
            RETURN QUERY SELECT * FROM public.fn_gestion_clinica_payload(FALSE, NULL, '{}'::JSONB);
            RETURN;
        END IF;

        RETURN QUERY
        SELECT * FROM public.fn_gestion_clinica_payload(
            TRUE,
            v_paciente.id_paciente,
            jsonb_build_object(
                'id_paciente', v_paciente.id_paciente,
                'rut', v_paciente.rut,
                'nombres', v_paciente.nombres,
                'apellido_paterno', v_paciente.apellido_paterno,
                'apellido_materno', COALESCE(v_paciente.apellido_materno, ''),
                'fecha_nacimiento', COALESCE(v_paciente.fecha_nacimiento, ''),
                'sexo', v_paciente.sexo,
                'telefono', COALESCE(v_paciente.telefono, ''),
                'direccion', COALESCE(v_paciente.direccion, ''),
                'id_region', v_paciente.id_region,
                'id_comuna', v_paciente.id_comuna
            )
        );

    ELSIF p_opcion = 20 THEN
        v_json := COALESCE(p_datos, '{}'::JSONB);
        v_rut_norm := UPPER(REGEXP_REPLACE(COALESCE(v_json->>'rut', ''), '[^0-9kK]', '', 'g'));

        IF LENGTH(v_rut_norm) < 2 THEN
            RAISE EXCEPTION 'El RUT es obligatorio.';
        END IF;
        IF COALESCE(TRIM(v_json->>'nombres'), '') = '' THEN
            RAISE EXCEPTION 'Los nombres son obligatorios.';
        END IF;
        IF COALESCE(TRIM(v_json->>'apellido_paterno'), '') = '' THEN
            RAISE EXCEPTION 'El apellido paterno es obligatorio.';
        END IF;
        IF COALESCE(TRIM(v_json->>'apellido_materno'), '') = '' THEN
            RAISE EXCEPTION 'El apellido materno es obligatorio.';
        END IF;
        IF COALESCE(v_json->>'fecha_nacimiento', '') = '' THEN
            RAISE EXCEPTION 'La fecha de nacimiento es obligatoria.';
        END IF;
        IF UPPER(COALESCE(v_json->>'sexo', '')) NOT IN ('M', 'F') THEN
            RAISE EXCEPTION 'El sexo es obligatorio.';
        END IF;
        IF COALESCE(TRIM(v_json->>'direccion'), '') = '' THEN
            RAISE EXCEPTION 'La dirección es obligatoria.';
        END IF;
        IF COALESCE(v_json->>'id_region', '') = '' OR COALESCE(v_json->>'id_comuna', '') = '' THEN
            RAISE EXCEPTION 'La región y la comuna son obligatorias.';
        END IF;
        IF COALESCE(TRIM(v_json->>'tipo_atencion'), '') = '' THEN
            RAISE EXCEPTION 'El tipo de atención es obligatorio.';
        END IF;
        IF COALESCE(TRIM(v_json->>'motivo_consulta'), '') = '' THEN
            RAISE EXCEPTION 'El motivo de la asistencia es obligatorio.';
        END IF;
        IF COALESCE(v_json->>'id_profesional_registra', '') = '' THEN
            RAISE EXCEPTION 'No se pudo identificar al profesional que registra la atención.';
        END IF;
        IF COALESCE(v_json->>'id_area_derivada', '') = '' THEN
            RAISE EXCEPTION 'El área de derivación es obligatoria.';
        END IF;

        v_id_region := (v_json->>'id_region')::UUID;
        v_id_comuna := (v_json->>'id_comuna')::UUID;
        v_id_profesional_registra := (v_json->>'id_profesional_registra')::UUID;
        v_id_area_derivada := NULLIF(v_json->>'id_area', '')::UUID;
        v_id_area_destino := (v_json->>'id_area_derivada')::UUID;

        IF NOT EXISTS (SELECT 1 FROM comuna co WHERE co.id_comuna = v_id_comuna AND co.id_region = v_id_region) THEN
            RAISE EXCEPTION 'La comuna no pertenece a la región seleccionada.';
        END IF;

        IF NOT EXISTS (SELECT 1 FROM profesional_salud ps WHERE ps.id_profesional = v_id_profesional_registra AND ps.activo) THEN
            RAISE EXCEPTION 'El profesional que registra la atención no está activo.';
        END IF;

        IF NOT EXISTS (SELECT 1 FROM area_profesional a WHERE a.id_area = v_id_area_destino AND a.activo) THEN
            RAISE EXCEPTION 'El área de derivación seleccionada no es válida.';
        END IF;

        SELECT ps.id_profesional INTO v_id_profesional_atiende
        FROM profesional_salud ps
        INNER JOIN disponibilidad_profesional dp ON dp.id_profesional = ps.id_profesional
        WHERE ps.id_area = v_id_area_destino
          AND ps.activo
          AND dp.disponible
          AND (dp.id_establecimiento IS NULL OR dp.id_establecimiento = NULLIF(v_json->>'id_establecimiento', '')::UUID)
          AND (dp.fecha_inicio IS NULL OR dp.fecha_inicio <= CURRENT_DATE)
          AND (dp.fecha_fin IS NULL OR dp.fecha_fin >= CURRENT_DATE)
        ORDER BY
            CASE WHEN dp.id_establecimiento IS NOT NULL THEN 0 ELSE 1 END,
            (SELECT COUNT(*) FROM atencion a WHERE a.id_profesional_atiende = ps.id_profesional AND a.estado = 'En curso'),
            ps.apellidos,
            ps.nombres
        LIMIT 1;

        IF v_id_profesional_atiende IS NULL THEN
            RAISE EXCEPTION 'No hay profesionales disponibles para el área seleccionada.';
        END IF;

        SELECT p.id_paciente INTO v_id_paciente
        FROM paciente p
        WHERE LOWER(REPLACE(REPLACE(p.rut, '.', ''), '-', '')) = LOWER(v_rut_norm)
        LIMIT 1;

        v_nuevo := v_id_paciente IS NULL;

        IF v_nuevo THEN
            INSERT INTO paciente (
                rut, nombres, apellidos, apellido_paterno, apellido_materno,
                fecha_nacimiento, sexo, telefono, direccion, id_region, id_comuna
            ) VALUES (
                SUBSTR(v_rut_norm, 1, LENGTH(v_rut_norm) - 1) || '-' || RIGHT(v_rut_norm, 1),
                TRIM(v_json->>'nombres'),
                TRIM(v_json->>'apellido_paterno') || ' ' || TRIM(v_json->>'apellido_materno'),
                TRIM(v_json->>'apellido_paterno'),
                TRIM(v_json->>'apellido_materno'),
                (v_json->>'fecha_nacimiento')::DATE,
                UPPER(v_json->>'sexo'),
                NULLIF(TRIM(v_json->>'telefono'), ''),
                TRIM(v_json->>'direccion'),
                v_id_region,
                v_id_comuna
            )
            RETURNING paciente.id_paciente INTO v_id_paciente;
        ELSE
            UPDATE paciente
            SET nombres = TRIM(v_json->>'nombres'),
                apellidos = TRIM(v_json->>'apellido_paterno') || ' ' || TRIM(v_json->>'apellido_materno'),
                apellido_paterno = TRIM(v_json->>'apellido_paterno'),
                apellido_materno = TRIM(v_json->>'apellido_materno'),
                fecha_nacimiento = (v_json->>'fecha_nacimiento')::DATE,
                sexo = UPPER(v_json->>'sexo'),
                telefono = NULLIF(TRIM(v_json->>'telefono'), ''),
                direccion = TRIM(v_json->>'direccion'),
                id_region = v_id_region,
                id_comuna = v_id_comuna
            WHERE paciente.id_paciente = v_id_paciente;
        END IF;

        IF COALESCE(v_json->>'id_tipo_alergia', '') <> '' THEN
            SELECT t.nombre INTO v_alergia_nombre
            FROM tipo_alergia t
            WHERE t.id_tipo_alergia::TEXT = v_json->>'id_tipo_alergia' AND t.activo;

            IF v_alergia_nombre IS NULL THEN
                RAISE EXCEPTION 'El tipo de alergia seleccionado no es válido.';
            END IF;

            INSERT INTO alergia (id_paciente, alergeno, criticidad)
            SELECT v_id_paciente,
                   v_alergia_nombre,
                   (SELECT c.valor FROM estado_clinica_catalogo c WHERE c.categoria = 'alergias' AND c.predeterminado AND c.activo LIMIT 1)
            WHERE NOT EXISTS (
                SELECT 1 FROM alergia a WHERE a.id_paciente = v_id_paciente AND a.alergeno = v_alergia_nombre
            );
        END IF;

        SELECT c.valor INTO v_estado
        FROM estado_clinica_catalogo c
        WHERE c.categoria = 'atenciones' AND c.valor = 'Programada' AND c.activo
        LIMIT 1;

        v_fecha := COALESCE(NULLIF(v_json->>'fecha_atencion', '')::DATE, CURRENT_DATE);

        INSERT INTO atencion (
            id_paciente, id_profesional, id_profesional_registra, id_profesional_atiende,
            id_area_derivada, id_area_destino, id_establecimiento, tipo_atencion,
            fecha_inicio, motivo_consulta, estado
        ) VALUES (
            v_id_paciente,
            v_id_profesional_atiende,
            v_id_profesional_registra,
            v_id_profesional_atiende,
            v_id_area_derivada,
            v_id_area_destino,
            NULLIF(v_json->>'id_establecimiento', '')::UUID,
            TRIM(v_json->>'tipo_atencion'),
            (v_fecha + LOCALTIME),
            TRIM(v_json->>'motivo_consulta'),
            COALESCE(v_estado, 'Programada')
        )
        RETURNING atencion.id_atencion INTO v_id_atencion;

        IF v_alergia_nombre IS NOT NULL THEN
            UPDATE alergia AS al
            SET id_atencion = v_id_atencion
            WHERE al.id_paciente = v_id_paciente
              AND al.alergeno = v_alergia_nombre
              AND al.id_atencion IS NULL
              AND al.fecha_registro >= CURRENT_TIMESTAMP - INTERVAL '1 minute';
        END IF;

        RETURN QUERY
        SELECT * FROM public.fn_gestion_clinica_payload(
            TRUE,
            v_id_atencion,
            jsonb_build_object(
                'id_atencion', v_id_atencion,
                'id_paciente', v_id_paciente,
                'paciente_nuevo', v_nuevo,
                'id_profesional_registra', v_id_profesional_registra,
                'id_profesional_atiende', v_id_profesional_atiende,
                'id_area_derivada', v_id_area_derivada,
                'id_area_destino', v_id_area_destino
            )
        );

    ELSE
        RAISE EXCEPTION 'Opción % no es válida para FN_GESTION_CLINICA', p_opcion;
    END IF;
END;
$$;


ALTER FUNCTION public.fn_gestion_clinica(p_opcion integer, p_rut character varying, p_id character varying, p_id_paciente uuid, p_id_establecimiento uuid, p_id_profesional uuid, p_tipo_atencion character varying, p_motivo_consulta text, p_estado character varying, p_fecha_inicio timestamp without time zone, p_fecha_fin timestamp without time zone, p_codigo_cie10 character varying, p_descripcion text, p_fecha_diagnostico date, p_alergeno character varying, p_tipo_reaccion character varying, p_criticidad character varying, p_observacion text, p_nombre_medicamento character varying, p_dosis character varying, p_frecuencia character varying, p_via_administracion character varying, p_tipo_examen character varying, p_resultado text, p_tipo_observacion character varying, p_valor text, p_unidad_medida character varying, p_datos jsonb) OWNER TO sichcp;

--
-- Name: fn_gestion_clinica_payload(boolean, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_gestion_clinica_payload(p_ok boolean, p_id uuid, p_json jsonb) RETURNS TABLE(encontrado boolean, id_registro uuid, id_paciente uuid, rut character varying, nombre_paciente character varying, id_atencion uuid, id_establecimiento uuid, id_profesional uuid, tipo_atencion character varying, motivo_consulta text, estado character varying, fecha_inicio timestamp without time zone, fecha_fin timestamp without time zone, codigo_cie10 character varying, descripcion text, fecha_diagnostico date, alergeno character varying, tipo_reaccion character varying, criticidad character varying, nombre_medicamento character varying, dosis character varying, frecuencia character varying, via_administracion character varying, tipo_examen character varying, resultado text, tipo_observacion character varying, valor text, unidad_medida character varying, fecha_registro timestamp without time zone, establecimiento_origen character varying, profesional_nombre character varying, nombre_completo character varying, edad integer, sexo character varying, recursos_ficha integer, atenciones integer, alergias_registradas integer, medicamentos_activos integer)
    LANGUAGE sql
    AS $$
    SELECT
        p_ok, p_id, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR, NULL::UUID, NULL::UUID, NULL::UUID,
        NULL::VARCHAR, NULL::TEXT, NULL::VARCHAR, NULL::TIMESTAMP, NULL::TIMESTAMP, NULL::VARCHAR,
        p_json::TEXT,
        NULL::DATE, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR,
        NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, NULL::TEXT, NULL::VARCHAR, NULL::TEXT,
        NULL::VARCHAR, NULL::TIMESTAMP, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, NULL::INT,
        NULL::VARCHAR, NULL::INT, NULL::INT, NULL::INT, NULL::INT;
$$;


ALTER FUNCTION public.fn_gestion_clinica_payload(p_ok boolean, p_id uuid, p_json jsonb) OWNER TO sichcp;

--
-- Name: fn_integraciones(numeric); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_integraciones(p_opcion numeric DEFAULT 1) RETURNS TABLE(fecha_integracion character varying, nombre_establecimiento character varying, tipo_establecimiento character varying, estado character varying, tipo_integracion character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_opcion = 1 THEN
    RETURN QUERY
    SELECT
      TO_CHAR(e.fecha_creacion, 'DD/MM/YYYY')::VARCHAR,
      e.nombre::VARCHAR,
      e.tipo_establecimiento::VARCHAR,
      'Conectado'::VARCHAR,
      'HL7 FHIR'::VARCHAR
    FROM establecimiento_salud e
    WHERE COALESCE(e.activo, TRUE) = TRUE
    ORDER BY e.fecha_creacion DESC
    LIMIT 5;

  ELSIF p_opcion = 2 THEN
    RETURN QUERY
    SELECT
      TO_CHAR(e.fecha_creacion, 'DD/MM/YYYY')::VARCHAR,
      e.nombre::VARCHAR,
      e.tipo_establecimiento::VARCHAR,
      'Conectado'::VARCHAR,
      'HL7 FHIR'::VARCHAR
    FROM establecimiento_salud e
    WHERE COALESCE(e.activo, TRUE) = TRUE
    ORDER BY e.fecha_creacion DESC;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_integraciones(p_opcion numeric) OWNER TO sichcp;

--
-- Name: fn_lista_indicadores(integer); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_lista_indicadores(p_opcion integer) RETURNS TABLE(orden integer, indicador character varying, valor bigint, subtitulo character varying, variacion character varying, icono character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pac_actual BIGINT;
  v_pac_porcentaje NUMERIC;
  v_ate_actual BIGINT;
  v_ate_porcentaje NUMERIC;
  v_est_actual BIGINT;
  v_rec_actual BIGINT;
  v_pac_variacion VARCHAR;
  v_ate_variacion VARCHAR;
  v_pac_porcentaje_str VARCHAR;
  v_ate_porcentaje_str VARCHAR;
  -- nuevos
  v_diag_actual BIGINT;
  v_diag_porcentaje NUMERIC;
  v_diag_porcentaje_str VARCHAR;
  v_diag_variacion VARCHAR;
  v_exam_actual BIGINT;
  v_exam_porcentaje NUMERIC;
  v_exam_porcentaje_str VARCHAR;
  v_exam_variacion VARCHAR;
  v_prof_actual BIGINT;
  v_prof_porcentaje NUMERIC;
  v_prof_porcentaje_str VARCHAR;
  v_prof_variacion VARCHAR;
BEGIN
  IF p_opcion = 1 THEN
    SELECT valor_actual, COALESCE(porcentaje_cambio, 0)
    INTO v_pac_actual, v_pac_porcentaje
    FROM public.indicador_historico
    WHERE id_indicador = 1
    ORDER BY fecha_registro DESC LIMIT 1;

    SELECT valor_actual, COALESCE(porcentaje_cambio, 0)
    INTO v_ate_actual, v_ate_porcentaje
    FROM public.indicador_historico
    WHERE id_indicador = 2
    ORDER BY fecha_registro DESC LIMIT 1;

    SELECT valor_actual INTO v_est_actual
    FROM public.indicador_historico
    WHERE id_indicador = 3
    ORDER BY fecha_registro DESC LIMIT 1;

    SELECT COUNT(*)::BIGINT INTO v_rec_actual
    FROM (
      SELECT 'Patient'::TEXT AS recurso, EXISTS (SELECT 1 FROM paciente LIMIT 1) AS disponible
      UNION ALL SELECT 'Encounter'::TEXT, EXISTS (SELECT 1 FROM atencion LIMIT 1)
      UNION ALL SELECT 'Condition'::TEXT, EXISTS (SELECT 1 FROM diagnostico LIMIT 1)
      UNION ALL SELECT 'AllergyIntolerance'::TEXT, EXISTS (SELECT 1 FROM alergia LIMIT 1)
      UNION ALL SELECT 'MedicationStatement'::TEXT, EXISTS (SELECT 1 FROM medicamento LIMIT 1)
      UNION ALL SELECT 'Observation'::TEXT, EXISTS (SELECT 1 FROM observacion_clinica LIMIT 1)
      UNION ALL SELECT 'DiagnosticReport'::TEXT, EXISTS (SELECT 1 FROM examen LIMIT 1)
      UNION ALL SELECT 'Practitioner'::TEXT, EXISTS (SELECT 1 FROM profesional_salud LIMIT 1)
    ) r WHERE r.disponible = TRUE;

    v_pac_porcentaje_str := REPLACE(
      (CASE WHEN v_pac_porcentaje >= 0 THEN '+' ELSE '' END) || v_pac_porcentaje::TEXT, '.', ','
    );
    v_ate_porcentaje_str := REPLACE(
      (CASE WHEN v_ate_porcentaje >= 0 THEN '+' ELSE '' END) || v_ate_porcentaje::TEXT, '.', ','
    );
    v_pac_variacion := v_pac_porcentaje_str || U&'% respecto al \00FAltimo registro';
    v_ate_variacion := v_ate_porcentaje_str || U&'% respecto al \00FAltimo registro';

    RETURN QUERY
    SELECT 1::INTEGER, 'Pacientes registrados'::VARCHAR, v_pac_actual,
           'Pacientes activos en la red'::VARCHAR, v_pac_variacion, 'bi-people'::VARCHAR
    UNION ALL
    SELECT 2, 'Atenciones realizadas', v_ate_actual,
           U&'Atenciones cl\00EDnicas cerradas', v_ate_variacion, 'bi-clipboard2-pulse'
    UNION ALL
    SELECT 3, 'Establecimientos conectados', v_est_actual,
           U&'Red p\00FAblica integrada', NULL::VARCHAR, 'bi-hospital'
    UNION ALL
    SELECT 4, 'Recursos FHIR disponibles', v_rec_actual,
           U&'Est\00E1ndar HL7 FHIR R4', NULL::VARCHAR, 'bi-diagram-3'
    ORDER BY 1;

  ELSIF p_opcion = 2 THEN
    RETURN QUERY
    SELECT 1::INTEGER, 'Hospitales'::VARCHAR,
           (SELECT COUNT(*) FROM establecimiento_salud WHERE tipo_establecimiento = 'HOSPITAL' AND COALESCE(activo, TRUE) = TRUE)::BIGINT,
           'conectados'::VARCHAR, NULL::VARCHAR, 'bi-hospital'::VARCHAR
    UNION ALL
    SELECT 2, 'CESFAM',
           (SELECT COUNT(*) FROM establecimiento_salud WHERE tipo_establecimiento = 'CESFAM' AND COALESCE(activo, TRUE) = TRUE)::BIGINT,
           'conectados', NULL::VARCHAR, 'bi-buildings-fill'
    UNION ALL
    SELECT 3, 'SAPU / SAR',
           (SELECT COUNT(*) FROM establecimiento_salud WHERE tipo_establecimiento IN ('SAPU','SAR') AND COALESCE(activo, TRUE) = TRUE)::BIGINT,
           'conectados', NULL::VARCHAR, 'bi-bandaid-fill'
    UNION ALL
    SELECT 4, 'Laboratorios',
           (SELECT COUNT(*) FROM establecimiento_salud WHERE tipo_establecimiento = 'LABORATORIO' AND COALESCE(activo, TRUE) = TRUE)::BIGINT,
           'conectados', NULL::VARCHAR, 'bi-flask-fill'
    ORDER BY 1;

  ELSIF p_opcion = 3 THEN
    SELECT valor_actual, COALESCE(porcentaje_cambio, 0)
    INTO v_diag_actual, v_diag_porcentaje
    FROM public.indicador_historico
    WHERE id_indicador = 5
    ORDER BY fecha_registro DESC LIMIT 1;

    SELECT valor_actual, COALESCE(porcentaje_cambio, 0)
    INTO v_exam_actual, v_exam_porcentaje
    FROM public.indicador_historico
    WHERE id_indicador = 6
    ORDER BY fecha_registro DESC LIMIT 1;

    SELECT valor_actual, COALESCE(porcentaje_cambio, 0)
    INTO v_prof_actual, v_prof_porcentaje
    FROM public.indicador_historico
    WHERE id_indicador = 7
    ORDER BY fecha_registro DESC LIMIT 1;

    v_diag_porcentaje_str := REPLACE(
      (CASE WHEN v_diag_porcentaje >= 0 THEN '+' ELSE '' END) || v_diag_porcentaje::TEXT, '.', ','
    );
    v_exam_porcentaje_str := REPLACE(
      (CASE WHEN v_exam_porcentaje >= 0 THEN '+' ELSE '' END) || v_exam_porcentaje::TEXT, '.', ','
    );
    v_prof_porcentaje_str := REPLACE(
      (CASE WHEN v_prof_porcentaje >= 0 THEN '+' ELSE '' END) || v_prof_porcentaje::TEXT, '.', ','
    );

    v_diag_variacion := v_diag_porcentaje_str || U&'% respecto al \00FAltimo registro';
    v_exam_variacion := v_exam_porcentaje_str || U&'% respecto al \00FAltimo registro';
    v_prof_variacion := v_prof_porcentaje_str || U&'% respecto al \00FAltimo registro';

    RETURN QUERY
    SELECT 5::INTEGER, U&'Diagn\00F3sticos registrados'::VARCHAR, v_diag_actual,
           U&'Diagn\00F3sticos cl\00EDnicos activos'::VARCHAR, v_diag_variacion, 'bi-clipboard2-heart'::VARCHAR
    UNION ALL
    SELECT 6, U&'Ex\00E1menes realizados', v_exam_actual,
           U&'Ex\00E1menes de laboratorio e imagen', v_exam_variacion, 'bi-file-earmark-medical'
    UNION ALL
    SELECT 7, 'Profesionales de salud', v_prof_actual,
           'Profesionales activos en la red', v_prof_variacion, 'bi-person-badge'
    ORDER BY 1;

  END IF;
END;
$$;


ALTER FUNCTION public.fn_lista_indicadores(p_opcion integer) OWNER TO sichcp;

--
-- Name: fn_lista_menu_byrol(uuid); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_lista_menu_byrol(p_id_rol uuid) RETURNS TABLE(id_menu uuid, nombre character varying, ruta character varying, id_menu_padre uuid, orden integer, es_padre boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.id_menu,
        m.nombre,
        m.ruta,
        m.id_menu_padre,
        m.orden,
        CASE 
            WHEN EXISTS (
                SELECT 1
                FROM menu sm
                WHERE sm.id_menu_padre = m.id_menu
                  AND sm.activo = TRUE
            )
            THEN TRUE
            ELSE FALSE
        END AS es_padre
    FROM menu m
    WHERE m.id_rol = p_id_rol
      AND m.activo = TRUE
            AND NOT (
                    EXISTS (
                            SELECT 1
                            FROM rol r
                            WHERE r.id_rol = p_id_rol
                                AND (r.codigo = 'SUPER_ADMIN' OR COALESCE(r.es_super_admin, FALSE))
                    )
                    AND EXISTS (
                            SELECT 1
                            FROM menu gestion_clinica
                            WHERE gestion_clinica.id_rol = p_id_rol
                                AND LOWER(TRANSLATE(gestion_clinica.nombre, 'ÁÉÍÓÚáéíóúÑñ', 'AEIOUaeiounn')) = 'gestion clinica'
                                AND (m.id_menu = gestion_clinica.id_menu OR m.id_menu_padre = gestion_clinica.id_menu)
                    )
            )
    ORDER BY
        CASE 
            WHEN m.id_menu_padre IS NULL THEN m.orden
            ELSE (
                SELECT mp.orden
                FROM menu mp
                WHERE mp.id_menu = m.id_menu_padre
            )
        END,
        m.id_menu_padre NULLS FIRST,
        m.orden;
END;
$$;


ALTER FUNCTION public.fn_lista_menu_byrol(p_id_rol uuid) OWNER TO sichcp;

--
-- Name: fn_login_sistema(character varying, character varying); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_login_sistema(p_username character varying, p_password_hash character varying) RETURNS TABLE(id_usuario uuid, nombres character varying, apellidos character varying, id_establecimiento uuid, nombre_establecimiento character varying, tipo_establecimiento character varying, comuna_establecimiento character varying, direccion_establecimiento character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        u.id_usuario,
        u.nombres,
        u.apellidos,
        u.id_establecimiento,
        (CASE 
            WHEN r.codigo = 'SUPER_ADMIN' OR r.es_super_admin = true THEN 'SICHCP'
            ELSE COALESCE(e.nombre, U&'Red P\00fablica SICHCP')::character varying 
        END) AS nombre_establecimiento,
        (CASE 
            WHEN r.codigo = 'SUPER_ADMIN' OR r.es_super_admin = true THEN U&'Administraci\00f3n Central'
            ELSE COALESCE(e.tipo_establecimiento, 'CENTRO DE SALUD')::character varying 
        END) AS tipo_establecimiento,
        (CASE 
            WHEN r.codigo = 'SUPER_ADMIN' OR r.es_super_admin = true THEN 'Santiago'
            ELSE COALESCE(e.comuna, 'Santiago')::character varying 
        END) AS comuna_establecimiento,
        (CASE 
            WHEN r.codigo = 'SUPER_ADMIN' OR r.es_super_admin = true THEN 'Nivel Central'
            ELSE COALESCE(e.direccion, '')::character varying 
        END) AS direccion_establecimiento
    FROM public.usuario_sistema u
    INNER JOIN public.rol r ON u.id_rol = r.id_rol
    LEFT JOIN public.establecimiento_salud e ON u.id_establecimiento = e.id_establecimiento
    WHERE u.username = p_username 
      AND u.password_hash = crypt(p_password_hash, u.password_hash) 
      AND COALESCE(u.activo, true) = true;
END;
$$;


ALTER FUNCTION public.fn_login_sistema(p_username character varying, p_password_hash character varying) OWNER TO sichcp;

--
-- Name: fn_mantenedor_imagenes(integer, uuid, character varying, character varying, character varying, character varying, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_mantenedor_imagenes(p_opcion integer, p_id_banner uuid DEFAULT NULL::uuid, p_tipo_banner character varying DEFAULT NULL::character varying, p_titulo character varying DEFAULT NULL::character varying, p_descripcion character varying DEFAULT NULL::character varying, p_nombre_imagen character varying DEFAULT NULL::character varying, p_url_imagen character varying DEFAULT NULL::character varying, p_orden integer DEFAULT NULL::integer, p_usuario_registro character varying DEFAULT NULL::character varying) RETURNS TABLE(id_banner uuid, tipo_banner character varying, titulo character varying, descripcion character varying, nombre_imagen character varying, url_imagen text, orden integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_opcion = 1 THEN
        RETURN QUERY
        SELECT 
            cb.id_banner,
            COALESCE(tb.nombre, cb.tipo_banner)::VARCHAR AS tipo_banner,
            cb.titulo,
            cb.descripcion,
            cb.nombre_imagen,
            cb.url_imagen,
            cb.orden
        FROM cfg_banner cb
        LEFT JOIN tipo_banner tb ON cb.id_tipo_banner = tb.id_tipo_banner
        WHERE cb.activo = TRUE
        ORDER BY cb.orden ASC;

    ELSIF p_opcion = 2 THEN
        RETURN QUERY
        SELECT 
            cb.id_banner,
            COALESCE(tb.nombre, cb.tipo_banner)::VARCHAR AS tipo_banner,
            cb.titulo,
            cb.descripcion,
            cb.nombre_imagen,
            cb.url_imagen,
            cb.orden
        FROM cfg_banner cb
        LEFT JOIN tipo_banner tb ON cb.id_tipo_banner = tb.id_tipo_banner
        WHERE cb.id_banner = p_id_banner;

    ELSIF p_opcion = 3 THEN
        IF p_id_banner IS NULL OR p_id_banner = '00000000-0000-0000-0000-000000000000'::UUID THEN
            INSERT INTO cfg_banner (
                id_tipo_banner,
                tipo_banner,
                titulo,
                descripcion,
                nombre_imagen,
                url_imagen,
                orden,
                usuario_registro
            ) VALUES (
                (SELECT tb.id_tipo_banner FROM tipo_banner tb WHERE tb.nombre = p_tipo_banner AND tb.activo = TRUE LIMIT 1),
                p_tipo_banner,
                p_titulo,
                p_descripcion,
                p_nombre_imagen,
                p_url_imagen,
                p_orden,
                COALESCE(NULLIF(p_usuario_registro, ''), 'SISTEMA')
            );

            RETURN QUERY
            SELECT 
                cb.id_banner,
                COALESCE(tb.nombre, cb.tipo_banner)::VARCHAR AS tipo_banner,
                cb.titulo,
                cb.descripcion,
                cb.nombre_imagen,
                cb.url_imagen,
                cb.orden
            FROM cfg_banner cb
            LEFT JOIN tipo_banner tb ON cb.id_tipo_banner = tb.id_tipo_banner
            ORDER BY cb.fecha_creacion DESC
            LIMIT 1;
        ELSE
            UPDATE cfg_banner cb
            SET 
                id_tipo_banner = COALESCE((SELECT tb.id_tipo_banner FROM tipo_banner tb WHERE tb.nombre = p_tipo_banner AND tb.activo = TRUE LIMIT 1), cb.id_tipo_banner),
                tipo_banner = COALESCE(p_tipo_banner, cb.tipo_banner),
                titulo = COALESCE(p_titulo, cb.titulo),
                descripcion = COALESCE(p_descripcion, cb.descripcion),
                nombre_imagen = COALESCE(p_nombre_imagen, cb.nombre_imagen),
                url_imagen = COALESCE(p_url_imagen, cb.url_imagen),
                orden = COALESCE(p_orden, cb.orden)
            WHERE cb.id_banner = p_id_banner;

            RETURN QUERY
            SELECT 
                cb.id_banner,
                COALESCE(tb.nombre, cb.tipo_banner)::VARCHAR AS tipo_banner,
                cb.titulo,
                cb.descripcion,
                cb.nombre_imagen,
                cb.url_imagen,
                cb.orden
            FROM cfg_banner cb
            LEFT JOIN tipo_banner tb ON cb.id_tipo_banner = tb.id_tipo_banner
            WHERE cb.id_banner = p_id_banner;
        END IF;

    ELSIF p_opcion = 4 THEN
        UPDATE cfg_banner cb
        SET activo = FALSE
        WHERE cb.id_banner = p_id_banner;

        RETURN QUERY
        SELECT 
            cb.id_banner,
            COALESCE(tb.nombre, cb.tipo_banner)::VARCHAR AS tipo_banner,
            cb.titulo,
            cb.descripcion,
            cb.nombre_imagen,
            cb.url_imagen,
            cb.orden
        FROM cfg_banner cb
        LEFT JOIN tipo_banner tb ON cb.id_tipo_banner = tb.id_tipo_banner
        WHERE cb.id_banner = p_id_banner;

    ELSIF p_opcion = 5 THEN
        RETURN QUERY
        SELECT 
            tb.id_tipo_banner AS id_banner,
            tb.nombre AS tipo_banner,
            NULL::VARCHAR AS titulo,
            tb.descripcion,
            NULL::VARCHAR AS nombre_imagen,
            NULL::TEXT AS url_imagen,
            0::INTEGER AS orden
        FROM tipo_banner tb
        WHERE tb.activo = TRUE
        ORDER BY tb.nombre ASC;
    END IF;
END;
$$;


ALTER FUNCTION public.fn_mantenedor_imagenes(p_opcion integer, p_id_banner uuid, p_tipo_banner character varying, p_titulo character varying, p_descripcion character varying, p_nombre_imagen character varying, p_url_imagen character varying, p_orden integer, p_usuario_registro character varying) OWNER TO sichcp;

