CREATE FUNCTION public.fn_muestra_imagenes(p_opcion numeric) RETURNS TABLE(id_banner uuid, tipo_banner character varying, titulo character varying, descripcion character varying, nombre_imagen character varying, url_imagen text, orden integer)
    LANGUAGE plpgsql
    AS $$ DECLARE v_opcion NUMERIC := p_opcion; BEGIN IF v_opcion = 1 THEN RETURN QUERY SELECT b.id_banner, b.tipo_banner, b.titulo, b.descripcion, b.nombre_imagen, b.url_imagen, b.orden FROM cfg_banner b WHERE b.activo = TRUE AND b.tipo_banner = 'Carrusel' ORDER BY b.orden ASC; END IF; END; $$;


