--
-- Name: fn_recursos_fhir(numeric); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_recursos_fhir(p_opcion numeric DEFAULT 1) RETURNS TABLE(orden integer, codigo character varying, nombre character varying, total_uso bigint, porcentaje_uso numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_opcion = 1 THEN
    RETURN QUERY
    WITH conteos AS (
      SELECT 'Patient'::VARCHAR AS cod, 'Paciente'::VARCHAR AS nom, COUNT(*)::BIGINT AS uso FROM paciente
      UNION ALL SELECT 'Condition', U&'Condici\00F3n', COUNT(*)::BIGINT FROM diagnostico
      UNION ALL SELECT 'AllergyIntolerance', 'Alergias', COUNT(*)::BIGINT FROM alergia
      UNION ALL SELECT 'MedicationStatement', 'Medicamentos', COUNT(*)::BIGINT FROM medicamento
      UNION ALL SELECT 'Observation', 'Observaciones', COUNT(*)::BIGINT FROM observacion_clinica
      UNION ALL SELECT 'Encounter', 'Atenciones', COUNT(*)::BIGINT FROM atencion
      UNION ALL SELECT 'DiagnosticReport', U&'Informe Diagn\00F3stico', COUNT(*)::BIGINT FROM examen
      UNION ALL SELECT 'Practitioner', 'Profesional de Salud', COUNT(*)::BIGINT FROM profesional_salud
    ),
    total AS (SELECT NULLIF(SUM(uso), 0) AS t FROM conteos)
    SELECT
      ROW_NUMBER() OVER (ORDER BY uso DESC)::INTEGER,
      cod, nom, uso,
      ROUND((uso::NUMERIC / (SELECT t FROM total)) * 100, 2)
    FROM conteos
    ORDER BY uso DESC
    LIMIT 5;

  ELSIF p_opcion = 2 THEN
    RETURN QUERY
    WITH conteos AS (
      SELECT 'Patient'::VARCHAR AS cod, 'Paciente'::VARCHAR AS nom, COUNT(*)::BIGINT AS uso FROM paciente
      UNION ALL SELECT 'Condition', U&'Condici\00F3n', COUNT(*)::BIGINT FROM diagnostico
      UNION ALL SELECT 'AllergyIntolerance', 'Alergias', COUNT(*)::BIGINT FROM alergia
      UNION ALL SELECT 'MedicationStatement', 'Medicamentos', COUNT(*)::BIGINT FROM medicamento
      UNION ALL SELECT 'Observation', 'Observaciones', COUNT(*)::BIGINT FROM observacion_clinica
      UNION ALL SELECT 'Encounter', 'Atenciones', COUNT(*)::BIGINT FROM atencion
      UNION ALL SELECT 'DiagnosticReport', U&'Informe Diagn\00F3stico', COUNT(*)::BIGINT FROM examen
      UNION ALL SELECT 'Practitioner', 'Profesional de Salud', COUNT(*)::BIGINT FROM profesional_salud
    ),
    total AS (SELECT NULLIF(SUM(uso), 0) AS t FROM conteos)
    SELECT
      ROW_NUMBER() OVER (ORDER BY uso DESC)::INTEGER,
      cod, nom, uso,
      ROUND((uso::NUMERIC / (SELECT t FROM total)) * 100, 2)
    FROM conteos
    ORDER BY uso DESC;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_recursos_fhir(p_opcion numeric) OWNER TO sichcp;

--
-- Name: fn_recursos_ficha_paciente(character varying); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_recursos_ficha_paciente(p_rut character varying) RETURNS TABLE(id_recurso uuid, fecha timestamp without time zone, tipo_recurso character varying, codigo_fhir character varying, descripcion text, establecimiento_origen character varying, estado character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_clean_rut VARCHAR;
    v_id_paciente UUID;
BEGIN
    v_clean_rut := LOWER(TRIM(REPLACE(REPLACE(COALESCE(p_rut, ''), '.', ''), '-', '')));

    SELECT p.id_paciente INTO v_id_paciente
    FROM paciente p
    WHERE LOWER(REPLACE(REPLACE(p.rut, '.', ''), '-', '')) = v_clean_rut
    LIMIT 1;

    IF v_id_paciente IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH alergias_agrupadas AS (
        SELECT
            (array_agg(al.id_alergia ORDER BY al.fecha_registro DESC NULLS LAST, al.id_alergia))[1] AS id_recurso,
            al.id_paciente,
            MAX(al.fecha_registro) AS fecha,
            MIN(al.alergeno) AS alergeno,
            string_agg(DISTINCT NULLIF(al.tipo_reaccion, ''), ', ') AS reacciones,
            CASE
                WHEN BOOL_OR(UPPER(COALESCE(al.criticidad, '')) = 'CRITICA') THEN 'CRITICA'
                WHEN BOOL_OR(UPPER(COALESCE(al.criticidad, '')) = 'ALTA') THEN 'ALTA'
                WHEN BOOL_OR(UPPER(COALESCE(al.criticidad, '')) = 'MODERADA') THEN 'MODERADA'
                WHEN BOOL_OR(UPPER(COALESCE(al.criticidad, '')) = 'BAJA') THEN 'BAJA'
                ELSE NULL
            END AS criticidad,
            COUNT(*)::INT AS total_registros
        FROM alergia al
        WHERE al.id_paciente = v_id_paciente
        GROUP BY al.id_paciente, LOWER(TRIM(al.alergeno))
    )
    SELECT a.id_atencion AS id_recurso,
           a.fecha_inicio AS fecha,
           'Atención'::VARCHAR AS tipo_recurso,
           'Encounter'::VARCHAR AS codigo_fhir,
           COALESCE(a.motivo_consulta, a.tipo_atencion, 'Consulta Médica Generada')::TEXT AS descripcion,
           COALESCE(e.nombre, 'Red Pública SICHCP')::VARCHAR AS establecimiento_origen,
           COALESCE(a.estado, 'Finalizado')::VARCHAR AS estado
    FROM atencion a
    LEFT JOIN establecimiento_salud e ON a.id_establecimiento = e.id_establecimiento
    WHERE a.id_paciente = v_id_paciente

    UNION ALL

    SELECT d.id_diagnostico AS id_recurso,
           d.fecha_registro AS fecha,
           'Diagnóstico'::VARCHAR AS tipo_recurso,
           'Condition'::VARCHAR AS codigo_fhir,
           (CASE WHEN d.codigo_cie10 IS NOT NULL AND d.codigo_cie10 <> '' THEN d.codigo_cie10 || ' - ' ELSE '' END || d.descripcion)::TEXT AS descripcion,
           COALESCE(e.nombre, 'Red Pública SICHCP')::VARCHAR AS establecimiento_origen,
           COALESCE(d.estado, 'Confirmado')::VARCHAR AS estado
    FROM diagnostico d
    LEFT JOIN atencion a ON d.id_atencion = a.id_atencion
    LEFT JOIN establecimiento_salud e ON a.id_establecimiento = e.id_establecimiento
    WHERE d.id_paciente = v_id_paciente

    UNION ALL

    SELECT ag.id_recurso,
           ag.fecha,
           'Alergia'::VARCHAR AS tipo_recurso,
           'AllergyIntolerance'::VARCHAR AS codigo_fhir,
           CONCAT_WS(' - ',
               ag.alergeno,
               NULLIF('Reacciones: ' || COALESCE(ag.reacciones, ''), 'Reacciones: '),
               NULLIF('Criticidad: ' || COALESCE(ag.criticidad, ''), 'Criticidad: '),
               CASE WHEN ag.total_registros > 1 THEN ag.total_registros::TEXT || ' registros asociados' END
           )::TEXT AS descripcion,
           COALESCE(e.nombre, 'Sin establecimiento asociado')::VARCHAR AS establecimiento_origen,
           'Registrada'::VARCHAR AS estado
    FROM alergias_agrupadas ag
    LEFT JOIN LATERAL (
        SELECT a.id_establecimiento
        FROM atencion a
        WHERE a.id_paciente = ag.id_paciente
        ORDER BY ABS(EXTRACT(EPOCH FROM (a.fecha_inicio - ag.fecha))), a.fecha_inicio DESC
        LIMIT 1
    ) origen ON TRUE
    LEFT JOIN establecimiento_salud e ON e.id_establecimiento = origen.id_establecimiento

    UNION ALL

    SELECT m.id_medicamento AS id_recurso,
           m.fecha_registro AS fecha,
           'Medicamento'::VARCHAR AS tipo_recurso,
           'MedicationRequest'::VARCHAR AS codigo_fhir,
           (m.nombre_medicamento || COALESCE(' ' || m.dosis, '') || COALESCE(' - ' || m.frecuencia, ''))::TEXT AS descripcion,
            COALESCE(e.nombre, 'Sin establecimiento asociado')::VARCHAR AS establecimiento_origen,
           COALESCE(m.estado, 'Activo')::VARCHAR AS estado
    FROM medicamento m
        LEFT JOIN LATERAL (
         SELECT a.id_establecimiento
         FROM atencion a
         WHERE a.id_paciente = m.id_paciente
         ORDER BY ABS(EXTRACT(EPOCH FROM (a.fecha_inicio - m.fecha_registro))), a.fecha_inicio DESC
         LIMIT 1
        ) origen ON TRUE
        LEFT JOIN establecimiento_salud e ON e.id_establecimiento = origen.id_establecimiento
        WHERE m.id_paciente = v_id_paciente

    UNION ALL

    SELECT ex.id_examen AS id_recurso,
           ex.fecha_registro AS fecha,
           'Examen'::VARCHAR AS tipo_recurso,
           'DiagnosticReport'::VARCHAR AS codigo_fhir,
           (ex.tipo_examen || COALESCE(': ' || ex.resultado, ''))::TEXT AS descripcion,
           COALESCE(e.nombre, 'Red Pública SICHCP')::VARCHAR AS establecimiento_origen,
           'Completado'::VARCHAR AS estado
    FROM examen ex
    LEFT JOIN establecimiento_salud e ON ex.id_establecimiento_origen = e.id_establecimiento
    WHERE ex.id_paciente = v_id_paciente

    UNION ALL

    SELECT obs.id_observacion AS id_recurso,
           obs.fecha_registro AS fecha,
           'Observación Clínica'::VARCHAR AS tipo_recurso,
           'Observation'::VARCHAR AS codigo_fhir,
           (obs.tipo_observacion || COALESCE(': ' || obs.valor || ' ' || COALESCE(obs.unidad_medida, ''), ''))::TEXT AS descripcion,
           COALESCE(e.nombre, 'Red Pública SICHCP')::VARCHAR AS establecimiento_origen,
           'Finalizado'::VARCHAR AS estado
    FROM observacion_clinica obs
    LEFT JOIN atencion a ON obs.id_atencion = a.id_atencion
    LEFT JOIN establecimiento_salud e ON a.id_establecimiento = e.id_establecimiento
    WHERE obs.id_paciente = v_id_paciente
    ORDER BY fecha DESC;
END;
$$;


ALTER FUNCTION public.fn_recursos_ficha_paciente(p_rut character varying) OWNER TO sichcp;

--
-- Name: fn_registrar_indicador_historico(integer, character varying, bigint); Type: FUNCTION; Schema: public; Owner: sichcp
--

CREATE FUNCTION public.fn_registrar_indicador_historico(p_id_indicador integer, p_nombre_indicador character varying, p_valor_actual bigint) RETURNS TABLE(valor_anterior bigint, valor_actual bigint, porcentaje_cambio numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valor_anterior BIGINT;
  v_porcentaje NUMERIC;
BEGIN
  SELECT valor_actual INTO v_valor_anterior
  FROM public.indicador_historico
  WHERE id_indicador = p_id_indicador
  ORDER BY fecha_registro DESC
  LIMIT 1;

  v_valor_anterior := COALESCE(v_valor_anterior, p_valor_actual);

  IF v_valor_anterior = 0 OR v_valor_anterior IS NULL THEN
    v_porcentaje := 0;
  ELSE
    v_porcentaje := ROUND(
      ((p_valor_actual::NUMERIC - v_valor_anterior::NUMERIC) / v_valor_anterior::NUMERIC) * 100,
      2
    );
  END IF;

  INSERT INTO public.indicador_historico (id_indicador, nombre_indicador, valor_anterior, valor_actual, porcentaje_cambio)
  VALUES (p_id_indicador, p_nombre_indicador, v_valor_anterior, p_valor_actual, v_porcentaje);

  RETURN QUERY SELECT v_valor_anterior, p_valor_actual, v_porcentaje;
END;
$$;


ALTER FUNCTION public.fn_registrar_indicador_historico(p_id_indicador integer, p_nombre_indicador character varying, p_valor_actual bigint) OWNER TO sichcp;

