CREATE FUNCTION public.fn_trigger_atencion_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_nuevo_valor BIGINT;
  v_valor_anterior BIGINT;
  v_porcentaje NUMERIC;
BEGIN
  SELECT COUNT(*) INTO v_nuevo_valor FROM public.atencion;
  
  SELECT valor_actual INTO v_valor_anterior
  FROM public.indicador_historico
  WHERE id_indicador = 2
  ORDER BY fecha_registro DESC
  LIMIT 1;
  
  v_valor_anterior := COALESCE(v_valor_anterior, v_nuevo_valor);
  
  IF v_valor_anterior = 0 THEN
    v_porcentaje := 0;
  ELSE
    v_porcentaje := ROUND(((v_nuevo_valor::NUMERIC - v_valor_anterior::NUMERIC) / v_valor_anterior::NUMERIC) * 100, 2);
  END IF;
  
  INSERT INTO public.indicador_historico (id_indicador, nombre_indicador, valor_anterior, valor_actual, porcentaje_cambio)
  VALUES (2, 'Atenciones realizadas', v_valor_anterior, v_nuevo_valor, v_porcentaje);
  
  RETURN NEW;
END;
$$;


